ALLOWED = {'gender': {'M','F','U'}, 'max_price': range(0, 2_000_001)}
def validate(a):
    out, err = {}, []
    for k, v in a.items():
        if k not in ALLOWED:
            err.append(f'모르는 필터 {k} 버림'); continue
        if v not in ALLOWED[k]:
            err.append(f'{k}={v} 범위 밖'); continue
        out[k] = v
    return out, err
print(validate({'gender':'F','max_price':150000,'user_id':77,'bundle':'3개묶음'}))
print(validate({'gender':'X','max_price':9_999_999}))
# 실행 결과
# ({'gender': 'F', 'max_price': 150000}, ['모르는 필터 user_id 버림', '모르는 필터 bundle 버림'])
# ({}, ['gender=X 범위 밖', 'max_price=9999999 범위 밖'])
